<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900}main{max-width:1400px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}.add{display:flex;gap:10px}.add input{flex:1;font:inherit;border:2px solid #dbe5e8;border-radius:12px;padding:13px}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:10px 8px 0 0}.secondary{background:#fff}.participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.pill{background:#d8f4f4;border-radius:999px;padding:7px 12px;cursor:pointer}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:230px!important;height:230px!important;border:10px solid #fff}.fullscreen{position:fixed;inset:0;background:#10283d;color:#fff;z-index:50;overflow:auto;padding:clamp(18px,3vw,48px)}.race-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}.race-top h1{font-size:clamp(30px,5vw,70px);line-height:.9;margin:0;letter-spacing:-.06em}.race-stage{max-width:1500px;margin:auto}.track{position:relative;height:clamp(68px,10vh,105px);border-bottom:2px dashed #6fc9d2;display:flex;align-items:center;padding-left:clamp(100px,13vw,220px);overflow:hidden}.track:after{content:'';position:absolute;right:7%;height:100%;border-left:4px solid #ffd45c}.duck{position:absolute;left:3%;z-index:2;text-align:center;font-size:clamp(35px,4vw,60px);--color:#ff7a59;animation:run var(--time) cubic-bezier(.12,.7,.2,1) var(--delay) forwards}.duck .name{display:block;margin-top:-5px;background:var(--color);color:#10283d;font-size:clamp(11px,1.2vw,17px);font-weight:900;padding:4px 10px;border-radius:999px;white-space:nowrap}@keyframes run{0%{left:3%;transform:translateY(0) rotate(-8deg)}50%{transform:translateY(-12px) rotate(7deg)}100%{left:86%;transform:translateY(0)}}.result{max-width:600px;margin:24px auto;background:#fff;color:#10283d;border-radius:18px;padding:18px;text-align:center}.muted{color:#637780;font-size:14px}@media(max-width:760px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.add{flex-direction:column}.track{padding-left:82px}}
</style></head><body><header>PATO NA PISTA 🦆</header><main id="app"><div class="hero"><div><small>SALA @{{ race.code }}</small><h1>Prepare os patos.</h1><p>@{{ race.names.length }} participantes cadastrados.</p></div><div style="font-size:90px">🦆</div></div><section class="panel"><div class="grid"><div class="full"><label>Cadastre os participantes</label><div class="add"><input v-model="newName" @keyup.enter="addName" placeholder="Digite um nome"><button @click="addName">Cadastrar nome</button></div><div class="participants"><span v-for="name in race.names" class="pill" @click="removeName(name)" title="Clique para remover">@{{ name }} ×</span></div><p class="muted">Clique em um nome para remover antes de começar.</p></div><div><button @click="startRace">Começar corrida</button><button class="secondary" @click="openQr">QR em tela cheia</button><button class="secondary" @click="exportCsv">Exportar CSV</button></div><div class="qr"><div id="qrcode"></div><span class="muted">Escaneie para entrar<br>@{{ joinUrl }}</span></div></div></section><div v-if="raceScreen" class="fullscreen"><div class="race-stage"><div class="race-top"><div><small>🏁 CORRIDA AO VIVO · SALA @{{ race.code }}</small><h1>@{{ finished?'🏆 Temos um campeão!':'Preparar... apontar... correr!' }}</h1></div><button class="secondary" @click="raceScreen=false">Sair</button></div><div v-for="(name,i) in race.names" class="track"><span class="duck" :style="duckStyle(name,i)">🦆<span class="name">@{{ name }}</span></span></div><div v-if="finished" class="result"><h2>🏆 @{{ winner }}</h2><strong>Campeão da corrida!</strong><ol><li v-for="r in race.results">@{{ r.position }}º — @{{ r.name }}</li></ol><button @click="raceScreen=false">Voltar ao painel</button></div></div></div><div v-if="showQr" class="fullscreen" style="background:#fffaf0;color:#10283d;display:grid;place-items:center"><div class="qr"><div><small>ESCANEIE PARA PARTICIPAR</small><h1>Pato na Pista</h1></div><div id="qrcodeFull"></div><button @click="showQr=false">Fechar</button></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:@json($race??null),newName:'',joinUrl:'',raceScreen:false,finished:false,showQr:false,order:[],winner:''}},mounted(){this.setup()},methods:{setup(){this.joinUrl=location.origin+'/join/'+this.race.code;setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:230,height:230}),50)},async addName(){const name=this.newName.trim();if(!name)return;const r=await fetch('/api/races/'+this.race.code+'/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,session:'organizer-'+crypto.randomUUID()})});if(r.ok){this.race=await r.json();this.newName=''}else alert((await r.json()).message||'Não foi possível cadastrar')},async removeName(name){this.race.names=this.race.names.filter(n=>n!==name);await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.race.names})})},duckStyle(name,i){const rank=this.order.indexOf(name)<0?i:this.order.indexOf(name);const colors=['#ff7a59','#ffd45c','#6ed6c0','#8eb8ff','#f49bd8','#c7a6ff'];return{'--color':colors[i%colors.length],'--time':(3.4+rank*.32)+'s','--delay':(Math.random()*.18)+'s'}},openQr(){this.showQr=true;setTimeout(()=>new QRCode(document.getElementById('qrcodeFull'),{text:this.joinUrl,width:520,height:520}),50)},async startRace(){if(this.race.names.length<2){alert('Cadastre pelo menos 2 participantes.');return}this.raceScreen=true;const next=await(await fetch('/api/races/'+this.race.code+'/start',{method:'POST'})).json();this.order=next.results.map(r=>r.name);this.winner=this.order[0];setTimeout(()=>{this.race=next;this.finished=true},5800)},exportCsv(){const a=document.createElement('a');a.href='data:text/csv,nome,posicao%0A'+(this.race.results||[]).map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
